#version 450
layout(location = 0) in vec2 uv;
layout(location = 0) out vec4 color;
layout(set = 0, binding = 0) uniform sampler2D source;
layout(set = 0, binding = 1) uniform Params { float threshold; } params;

void main() {
    vec4 c = texture(source, uv);
    vec3 straight = c.a > 0.0 ? c.rgb / c.a : vec3(0.0);
    float luma = dot(straight, vec3(0.2126, 0.7152, 0.0722));
    color = c * smoothstep(params.threshold, params.threshold + 0.1, luma);
}

#version 450
layout(location = 0) in vec2 uv;
layout(location = 0) out vec4 color;
layout(set = 0, binding = 0) uniform sampler2D source;
layout(set = 0, binding = 1) uniform Params { vec2 direction; float radius; } params;

void main() {
    // radius in pixels of the input, along direction.
    vec2 stride = params.direction * (params.radius / 12.0) / vec2(textureSize(source, 0));
    vec4 sum = vec4(0.0);
    float total = 0.0;
    for (int i = -12; i <= 12; i++) {
        float weight = exp(-0.5 * float(i * i) / 36.0);
        sum += texture(source, uv + stride * float(i)) * weight;
        total += weight;
    }
    color = sum / total;
}

