#version 450
layout(location = 0) in vec2 uv;
layout(location = 0) out vec4 color;
layout(set = 0, binding = 0) uniform sampler2D source;
layout(set = 0, binding = 1) uniform sampler2D glow;
layout(set = 0, binding = 2) uniform Params { float intensity; } params;

void main() {
    // Unconnected, source reads the layer; glow comes from the blur.
    color = texture(source, uv) + texture(glow, uv) * params.intensity;
}
